// ❌ OLD: ThreadLocal-based request context. Every virtual thread
// (or pooled thread) that runs a request gets a ThreadLocalMap entry.
// If the code forgets USER.remove(), the value (and everything it
// references) is pinned for the lifetime of the thread — with millions
// of short-lived virtual threads, this is a memory-leak factory.
public class ContextLegacy {
  private static final ThreadLocal<String> USER = new ThreadLocal<>(); // ❌ OLD

  public static void handle(Request req) {
    USER.set(req.userId()); // ❌ OLD: mutable, per-thread storage
    try {
      doWork();
    } finally {
      // ❌ OLD: if this finally is forgotten, USER leaks; also the value
      // is visible to OTHER code on this thread that shouldn't see it.
      USER.remove();
    }
  }

  static void doWork() {
    String u = USER.get();
    // ...
  }
}

import java.util.concurrent.ScopedValue;

// ✅ NEW: ScopedValue binds an immutable value for the duration of a
// scope. No manual cleanup, no per-thread storage, safe across virtual
// threads, and read-only (cannot be mutated mid-request).
public class ContextModern {
  private static final ScopedValue<String> USER = ScopedValue.newInstance(); // ✅ NEW

  public static void handle(Request req) {
    // ✅ NEW: the binding is installed for the run() call only
    ScopedValue.where(USER, req.userId()).run(() -> {
      doWork(); // USER.get() works here and in anything it calls
    });
    // ✅ NEW: after run() returns, USER.get() throws NoSuchElementException
  }

  static void doWork() {
    String u = USER.get(); // ✅ NEW: O(1) read of the current binding
    // ...
  }
}
